12	// assertIllegalOrderingFailure 校验“依赖先后关系不合法”记录重开后的统一形态：
13	// 失败、BlockerID 为 0、无成功归档与实际输入，原因指出保存的依赖顺序中第一个
14	// 不合法的作业号并说明它不能作为本作业的上游；按作业号读取与按提交人列举一致，
15	// 落盘记录同样已改写。
16	func assertIllegalOrderingFailure(t *testing.T, s *Store, id, badID, selfID uint64) {
17		t.Helper()
18		g, err := s.Get(id)
19		if err != nil {
20			t.Fatal(err)
21		}
22		if g.Status != StatusFailed {
23			t.Fatalf("job %d must fail on illegal dependency ordering, got %s", id, g.Status)
24		}
25		if g.BlockerID != 0 {
26			t.Fatalf("illegal ordering is the job's own error: job %d blocker=%d want 0", id, g.BlockerID)
27		}
28		if g.Archive != nil || g.EffectiveValues != nil {
29			t.Fatalf("job %d must not return archive/effective inputs: archive=%v effective=%v",
30				id, g.Archive, g.EffectiveValues)
31		}
32		if !strings.Contains(g.FailureReason, "依赖先后关系不合法") ||
33			!strings.Contains(g.FailureReason, "作业 "+itoa(badID)) ||
34			!strings.Contains(g.FailureReason, "不能作为本作业的上游") {
35			t.Fatalf("job %d reason=%q must name first illegal upstream %d (self=%d) as unable to precede it",
36				id, g.FailureReason, badID, selfID)
37		}
38		if g.FinishedAt.IsZero() {
39			t.Fatalf("job %d failed record must keep a finished time", id)
40		}
41	
42		listed, err := s.List(g.Submitter, time.Time{}, time.Time{})
43		if err != nil {
44			t.Fatal(err)
45		}
46		found := false
47		for _, lj := range listed {
48			if lj.ID != id {
49				continue
50			}
51			found = true
52			if lj.Status != StatusFailed || lj.BlockerID != 0 ||
53				lj.Archive != nil || lj.EffectiveValues != nil ||
54				lj.FailureReason != g.FailureReason {
55				t.Fatalf("listed job %d disagrees with Get: status=%s blocker=%d reason=%q",
56					id, lj.Status, lj.BlockerID, lj.FailureReason)
57			}
58		}
59		if !found {
60			t.Fatalf("job %d missing from submitter listing", id)
61		}
62	
63		data, err := os.ReadFile(filepath.Join(s.Dir(), jobFileName(id)))
64		if err != nil {
65			t.Fatal(err)
66		}
67		text := string(data)
68		if !strings.Contains(text, `"status": "failed"`) {
69			t.Fatalf("job %d on-disk record must be failed:\n%s", id, text)
70		}
71		// blocker 为 0 时按 omitempty 不落盘；出现任何 blocker_id 都说明根因错误。
72		if strings.Contains(text, `"blocker_id"`) {
73			t.Fatalf("job %d on-disk record must have no blocker root:\n%s", id, text)
74		}
75		if strings.Contains(text, `"archive"`) {
76			t.Fatalf("job %d on-disk record must not retain archive:\n%s", id, text)
77		}
