80	// 规格示例：作业 7 保存了对作业 7 自身的依赖，原始序列 [0]，实际输入 [0,0]，
81	// 总和、平方和、日志、摘要和校验值全部自洽——重开后仍必须判失败。等待它的
82	// 下游按既有依赖失败规则处理，根因沿合法依赖链保留为作业 7；被引用者就是
83	// 它自己，不能把任何其他有效作业判成失败。
84	func TestReopenRejectsSelfConsistentSelfDependency(t *testing.T) {
85		dir := t.TempDir()
86		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
87		// 作业 7：依赖 [7]（引用自己），实际输入 [0,0]（sum=0、sq=0，全套自洽）。
88		self := syntheticSucceededRecord(t, dir, 7, []int64{0}, []int64{0, 0}, []uint64{7}, base)
89		if self.archive.Sum != 0 || self.archive.SumOfSquares != 0 {
90			t.Fatalf("self-dep premise: sum=%d sq=%d want 0,0", self.archive.Sum, self.archive.SumOfSquares)
91		}
92		// 作业 8：合法排队下游，等待作业 7。
93		writeSyntheticRecord(t, dir, &storedJob{
94			id: 8, submitter: "a", requestID: "child",
95			values: []int64{20}, dependencies: []uint64{7},
96			queuedAt: base.Add(8 * time.Second),
97			status:   StatusQueued,
98		})
99		// 作业 9：更下游，只依赖作业 8，根因应沿合法链条保留为作业 7。
100		writeSyntheticRecord(t, dir, &storedJob{
101			id: 9, submitter: "a", requestID: "grandchild",
102			values: []int64{30}, dependencies: []uint64{8},
103			queuedAt: base.Add(9 * time.Second),
104			status:   StatusQueued,
105		})
106		// 作业 10：无关排队作业，重开后照常完成。
107		writeSyntheticRecord(t, dir, &storedJob{
108			id: 10, submitter: "b", requestID: "indep",
109			values:   []int64{1, 2, 3},
110			queuedAt: base.Add(10 * time.Second),
111			status:   StatusQueued,
112		})
113	
114		s, err := Open(dir)
115		if err != nil {
116			t.Fatal(err)
117		}
118		defer s.Close()
119	
120		assertIllegalOrderingFailure(t, s, 7, 7, 7)
121	
122		// 原始提交内容与已有时间信息保留；成功记录已有完成时间，不重新填写。
123		g7, _ := s.Get(7)
124		if len(g7.Values) != 1 || g7.Values[0] != 0 || len(g7.Dependencies) != 1 || g7.Dependencies[0] != 7 {
125			t.Fatalf("self-dep record must keep original submission content: values=%v deps=%v",
126				g7.Values, g7.Dependencies)
127		}
128		if !g7.QueuedAt.Equal(base.Add(7*time.Second)) ||
129			!g7.StartedAt.Equal(base.Add(7*time.Second+time.Millisecond)) ||
130			!g7.FinishedAt.Equal(base.Add(8*time.Second)) {
131			t.Fatalf("self-dep record must keep existing timestamps: queued=%s started=%s finished=%s",
132				g7.QueuedAt, g7.StartedAt, g7.FinishedAt)
133		}
134	
135		// 下游按既有依赖失败规则处理：直接上游 7，根因也是 7；不能继续等待或产生归档。
136		child := waitStatus(t, s, 8, StatusFailed)
137		if child.BlockerID != 7 {
138			t.Fatalf("child blocker=%d want root 7 (the illegal record itself)", child.BlockerID)
139		}
140		if !strings.Contains(child.FailureReason, "直接上游作业 7") ||
141			!strings.Contains(child.FailureReason, "依赖先后关系不合法") {
142			t.Fatalf("child must name direct upstream 7 and carry its ordering reason: %q",
143				child.FailureReason)
144		}
145		if child.Archive != nil || !child.StartedAt.IsZero() {
146			t.Fatalf("blocked child must never compute: started=%s archive=%v",
147				child.StartedAt, child.Archive)
148		}
149		// 根因沿合法依赖链保留：作业 9 的直接上游是 8，根因仍是 7。
150		grand := waitStatus(t, s, 9, StatusFailed)
151		if grand.BlockerID != 7 {
152			t.Fatalf("grandchild blocker=%d want root 7 preserved along legal chain", grand.BlockerID)
153		}
154		if !strings.Contains(grand.FailureReason, "直接上游作业 8") ||
155			!strings.Contains(grand.FailureReason, "根因为作业 7") {
156			t.Fatalf("grandchild must name direct upstream 8 and root 7: %q", grand.FailureReason)
157		}
158	
159		// 无关作业照常成功。
160		indep := waitStatus(t, s, 10, StatusSucceeded)
161		if indep.Archive.Sum != 6 || indep.Archive.SumOfSquares != 14 {
162			t.Fatalf("unrelated job result=%d,%d want 6,14", indep.Archive.Sum, indep.Archive.SumOfSquares)
163		}
164	
165		// 再次重开：失败结果已保存在目录中，状态、原因与根因保持稳定。
166		if err := s.Close(); err != nil {
167			t.Fatal(err)
168		}
169		s2, err := Open(dir)
170		if err != nil {
171			t.Fatal(err)
172		}
173		defer s2.Close()
174		assertIllegalOrderingFailure(t, s2, 7, 7, 7)
175		for _, id := range []uint64{8, 9} {
176			g := waitStatus(t, s2, id, StatusFailed)
177			if g.BlockerID != 7 {
178				t.Fatalf("after second reopen job %d blocker=%d want 7", id, g.BlockerID)
179			}
180		}
181	}
